import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { listDocuments } from "@/actions/documents";
import { DocumentList } from "@/components/artifacts/document-list";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("artifacts");
  return { title: t("page.title") };
}

/**
 * Artifacts page — server component.
 *
 * Lists every artifact (AI-generated document — report, code, text,
 * sheet, image, or a product's own custom kind) this user has created
 * in the active workspace, backed by `@intelligo-dev/core/documents`
 * (ADR-0009). Filtering by type and the content-preview dialog are
 * client-side (`components/artifacts/document-list.tsx`); this page
 * only fetches the full, unfiltered set once.
 *
 * `dynamic = "force-dynamic"`: `listDocuments()` reads request-scoped
 * session and workspace state (`requireWorkspace()`, inside
 * `@/actions/documents`), so this page can only ever render per-request
 * — declaring that stops Next from attempting a static prerender that
 * would always fail at build time.
 */
export const dynamic = "force-dynamic";

export default async function ArtifactsPage() {
  const [t, result] = await Promise.all([
    getTranslations("artifacts"),
    listDocuments(),
  ]);

  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle>{t("page.heading")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      {result.success ? (
        <DocumentList documents={result.data} />
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>{t("page.unavailableTitle")}</CardTitle>
            <CardDescription>{result.error}</CardDescription>
          </CardHeader>
        </Card>
      )}
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

export default function ArtifactsLoading() {
  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <div className="space-y-2">
        <Skeleton className="h-7 w-32" />
        <Skeleton className="h-4 w-80" />
      </div>

      <div className="flex flex-wrap gap-2">
        {Array.from({ length: 3 }).map((_, index) => (
          <Skeleton key={index} className="h-8 w-20 rounded-full" />
        ))}
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {Array.from({ length: 6 }).map((_, index) => (
          <Card key={index} className="p-5">
            <div className="mb-3 flex items-start gap-3">
              <Skeleton className="size-4 rounded" />
              <div className="min-w-0 flex-1 space-y-2">
                <Skeleton className="h-5 w-48" />
                <Skeleton className="h-4 w-16 rounded-full" />
              </div>
            </div>
            <div className="flex items-center justify-between">
              <Skeleton className="h-4 w-28" />
              <Skeleton className="h-7 w-16 rounded" />
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

"use client";

/**
 * Client error boundary for the artifacts route. Self-contained per the
 * repo-wide registry standard: no shared app-internal error component,
 * no error-reporting SDK.
 */

import { useEffect } from "react";
import { useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Link } from "@/i18n/navigation";

export default function ArtifactsError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const t = useTranslations("artifacts");

  useEffect(() => {
    console.error("[artifacts] error boundary caught:", error);
  }, [error]);

  return (
    <div className="flex min-h-96 items-center justify-center p-4">
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertDescription>{t("error.description")}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("error.retry")}</Button>
          <Button
            variant="outline"
            render={<Link href="/" />}
            nativeButton={false}
          >
            {t("error.goHome")}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use server";

/**
 * Artifact (document) server actions — thin transport over
 * `@intelligo-dev/core/documents` (ADR-0009): resolve the caller's actor via
 * `requireWorkspace()`, call the core documents service, map any
 * `DocumentServiceError` to a friendly message, and reshape the result
 * for the page and its components. No business rules here — those live
 * in `@intelligo-dev/core/documents`.
 *
 * Only `getUserDocuments` and `deleteDocumentVersions` are wired here:
 * this item is a read/browse artifact library page, not the artifact
 * editor. `saveDocument` is called from wherever your product's AI tool
 * calls create/update an artifact mid-conversation (the `chat` item),
 * not from this page. `getDocument` (single-item fetch) isn't needed
 * either — the list already carries each artifact's full content.
 *
 * `deleteDocumentVersions(actor, id, timestamp)` deletes every version
 * created strictly *after* `timestamp`, bounded to the last 30 days —
 * it's a revert primitive (undo edits back to a checkpoint), not a
 * generic "delete this artifact forever" call, and the service exposes
 * no way to look up an artifact's *earliest* version. `deleteLatestVersion`
 * below uses it the only way this page's data supports honestly: delete
 * the single version this page already has, by passing a timestamp one
 * millisecond before it. When that version is the artifact's only one,
 * the artifact disappears; when older versions exist, the artifact
 * reverts to the previous one instead of disappearing —
 * `components/document-actions.tsx`'s confirm dialog says so.
 *
 * Product-specific document title patterns (for custom agent labels and
 * the "report" filter) register through `@intelligo-dev/core/documents`'s
 * `registerDocumentPatterns` — see `@/lib/document-patterns.ts`, this
 * item's composition-root extension point. Nothing in this file calls
 * it: per ADR-0005 (no import-side-effect registration), that
 * registration happens once, at startup, from an explicit composition
 * root — never from a request-scoped file like this one, and never as
 * an import side effect.
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  deleteDocumentVersions,
  getUserDocuments,
  isDocumentServiceError,
  isProductDocument,
  type DocumentListItem,
} from "@intelligo-dev/core/documents";

export type ActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

/**
 * A document list item plus whether its title matches a pattern
 * registered through `@/lib/document-patterns.ts` — drives the
 * "Reports" filter tab.
 */
export type ArtifactListItem = DocumentListItem & { isReport: boolean };

type Translator = Awaited<ReturnType<typeof getTranslations>>;

function friendlyMessageKey(code: string): string | undefined {
  switch (code) {
    case "not_found":
      return "actions.notFound";
    case "forbidden":
      return "actions.forbidden";
    case "invalid_input":
      return "actions.invalidInput";
    case "database_error":
      return "actions.databaseError";
    default:
      return undefined;
  }
}

function friendlyError(t: Translator, error: unknown): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isDocumentServiceError(error)) {
    const key = friendlyMessageKey(error.code);
    return key ? t(key) : t("actions.genericError");
  }
  return t("actions.genericError");
}

/**
 * Every artifact the caller owns in the active workspace, most recently
 * created first. Filtering (by kind, or by the "report" flag) happens
 * client-side in `document-list.tsx` — this always returns the full
 * set.
 */
export async function listDocuments(): Promise<
  ActionResult<ArtifactListItem[]>
> {
  try {
    const { workspace, user } = await requireWorkspace();
    const documents = await getUserDocuments({
      workspaceId: workspace.id,
      userId: user.id,
    });

    return {
      success: true,
      data: documents.map((doc) => ({
        ...doc,
        isReport: isProductDocument(doc.title),
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("artifacts"), error),
    };
  }
}

/**
 * Deletes the version of the artifact this page already has. See the
 * module doc comment above for exactly what that does and doesn't
 * guarantee. `latestCreatedAt` must be that version's own `createdAt`
 * (ISO string), as returned by `listDocuments`.
 */
export async function deleteLatestVersion(
  id: string,
  latestCreatedAt: string
): Promise<ActionResult<undefined>> {
  const latest = new Date(latestCreatedAt);
  if (Number.isNaN(latest.getTime())) {
    const t = await getTranslations("artifacts");
    return { success: false, error: t("actions.invalidTimestamp") };
  }

  try {
    const { workspace, user } = await requireWorkspace();
    const cutoff = new Date(latest.getTime() - 1).toISOString();

    await deleteDocumentVersions(
      { workspaceId: workspace.id, userId: user.id },
      id,
      cutoff
    );

    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("artifacts"), error),
    };
  }
}

import "server-only";

/**
 * Document title-pattern registration — composition-root extension
 * point for the `artifacts` item.
 *
 * `@intelligo-dev/core/documents` keeps a small classifier registry
 * (`registerDocumentPatterns`) that maps a document's title to a human
 * agent label (rendered on every artifact card) and to the "Reports"
 * filter tab (`isProductDocument`, used by `@/actions/documents`). Per
 * ADR-0005 (no import-side-effect registration), populating that
 * registry happens once, at startup, from an explicit composition root
 * your app owns — never by importing this file for its side effects,
 * and never from a request-scoped file (a Server Action, a page) where
 * it could run more than once and push duplicate entries onto the same
 * in-memory registry.
 *
 * Ships no registrations by default: a fresh install has no product to
 * label, and the classifier already falls back to a generic "AI
 * Assistant" label with no registrations at all. Call the function
 * below exactly once, from your composition root, after adding your own
 * product's title patterns (uncomment and adjust the example call). If
 * your app already has a composition root (e.g. the pattern
 * `@/lib/ensure-composed` guards against), call it from
 * there, guarded the same way every other registration is.
 */
export function registerDefaultDocumentPatterns(): void {
  // Registers nothing by default.
}

// Example — brand documents your product's chat agent creates with a
// custom agent label and fold them into the "Reports" filter (uncomment
// and adjust; remove the no-op export above):
//
// import { registerDocumentPatterns } from "@intelligo-dev/core/documents";
//
// export function registerDefaultDocumentPatterns(): void {
//   registerDocumentPatterns({
//     productSlug: "default",
//     agentLabel: "Assistant",
//     patterns: ["report", "summary"],
//   });
// }

"use client";

/**
 * DocumentList — client component that renders the artifact grid with
 * type-based filtering and a full-content preview dialog.
 *
 * Generalizes the first product's `document-list.tsx`: the "Reports"
 * filter is `doc.isReport`, computed server-side in `@/actions/documents`
 * from `@intelligo-dev/core/documents`'s classifier registry — not a
 * hardcoded title-pattern match — and the kind tabs are derived
 * from whatever `kind` values are actually present in the data, so a
 * product that saves a custom kind beyond text/code/sheet/image still
 * gets a working filter tab for it, with no changes to this file.
 *
 * Delete is optimistic-local: `document-actions.tsx` calls the server
 * action itself, and this component only removes the item from its own
 * state on success (the same uncontrolled-list pattern the
 * `notifications` and `team-settings` items use) — no full page
 * `router.refresh()` round trip needed to see the item disappear.
 */

import { useEffect, useMemo, useState } from "react";
import type { ComponentProps } from "react";
import { useFormatter, useTranslations } from "next-intl";
import { Bot, Code, File, FileText, ImageIcon, Sheet } from "lucide-react";
import { Streamdown } from "streamdown";
import { cjk } from "@streamdown/cjk";
import { code } from "@streamdown/code";
import { math } from "@streamdown/math";
import { mermaid } from "@streamdown/mermaid";
import "katex/dist/katex.min.css";

import { Link } from "@/i18n/navigation";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { CodeBlock } from "@/components/ui/ai-code-block";

import type { ArtifactListItem } from "@/actions/documents";
import { DocumentActions } from "./document-actions";

// The plugin packages type `Pluggable` against their own `unified`
// copy; the shapes are the ones Streamdown expects.
const MARKDOWN_PLUGINS = { code, math, mermaid, cjk } as unknown as NonNullable<
  ComponentProps<typeof Streamdown>["plugins"]
>;

const LANGUAGE_BY_EXTENSION: Record<string, string> = {
  ts: "typescript",
  tsx: "tsx",
  js: "javascript",
  jsx: "jsx",
  py: "python",
  rb: "ruby",
  go: "go",
  rs: "rust",
  java: "java",
  kt: "kotlin",
  swift: "swift",
  cs: "csharp",
  sh: "bash",
  sql: "sql",
  json: "json",
  yaml: "yaml",
  yml: "yaml",
  md: "markdown",
  html: "html",
  css: "css",
};

type CodeLanguage = ComponentProps<typeof CodeBlock>["language"];

/** The language a code document is shown in, from its title's extension. */
function languageOf(title: string): CodeLanguage {
  const extension = title.split(".").pop()?.toLowerCase() ?? "";
  return (LANGUAGE_BY_EXTENSION[extension] ?? "text") as CodeLanguage;
}

/**
 * A document reads the way it was written: notes and drafts as
 * markdown (math and diagrams included), code highlighted with line
 * numbers, a sheet as its raw rows, an image as itself. An unknown
 * kind falls back to plain text rather than nothing.
 */
function DocumentContent({ kind, title, content }: { kind: string; title: string; content: string }) {
  switch (kind) {
    case "code":
      return <CodeBlock code={content} language={languageOf(title)} showLineNumbers />;
    case "sheet":
      return (
        <pre className="overflow-x-auto px-1 font-mono text-xs leading-relaxed whitespace-pre">
          {content}
        </pre>
      );
    case "image":
      return <img src={content} alt={title} className="max-w-full rounded-md" />;
    case "text":
      return (
        <div className="prose prose-sm max-w-none px-1 dark:prose-invert">
          <Streamdown plugins={MARKDOWN_PLUGINS}>{content}</Streamdown>
        </div>
      );
    default:
      return (
        <div className="px-1 text-sm leading-relaxed whitespace-pre-wrap">{content}</div>
      );
  }
}

function kindIcon(kind: string) {
  switch (kind) {
    case "code":
      return <Code className="size-4 shrink-0" />;
    case "sheet":
      return <Sheet className="size-4 shrink-0" />;
    case "image":
      return <ImageIcon className="size-4 shrink-0" />;
    default:
      return <FileText className="size-4 shrink-0" />;
  }
}

interface DocumentListProps {
  documents: ArtifactListItem[];
}

/**
 * Relative timestamp that can't cause a hydration mismatch: the server
 * (and the first client render) show a locale-formatted absolute date,
 * and an effect swaps in the relative form once mounted — `Date.now()`
 * during render would differ between server and client.
 */
function RelativeTime({ iso }: { iso: string }) {
  const format = useFormatter();
  const [now, setNow] = useState<Date | null>(null);
  useEffect(() => setNow(new Date()), []);
  const date = new Date(iso);
  return (
    <>
      {now
        ? format.relativeTime(date, now)
        : format.dateTime(date, { dateStyle: "medium" })}
    </>
  );
}

export function DocumentList({ documents }: DocumentListProps) {
  const t = useTranslations("artifacts");
  const [items, setItems] = useState(documents);
  const [activeFilter, setActiveFilter] = useState<string>("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // `/artifacts?document=<id>` — the chat canvas's "Open in Artifacts" —
  // lands on that document's preview.
  useEffect(() => {
    const id = new URLSearchParams(window.location.search).get("document");
    if (id) setSelectedId(id);
  }, []);

  /**
   * A known kind (text/code/sheet/image) resolves through this item's
   * own messages; a product-defined custom kind (see the module doc
   * comment above) falls back to capitalizing the raw value — `t.has`
   * is the check next-intl exposes for "does this key exist" without
   * throwing.
   */
  function kindLabel(kind: string): string {
    const key = `filters.kind.${kind}`;
    return t.has(key) ? t(key) : kind.charAt(0).toUpperCase() + kind.slice(1);
  }

  // A kind is a category, not a status: every kind reads the same, and a
  // report — the one kind that means something extra — stands out as secondary.
  function badgeFor(doc: ArtifactListItem): {
    label: string;
    variant: "secondary" | "outline";
  } {
    if (doc.isReport) {
      return { label: t("badge.report"), variant: "secondary" };
    }
    return { label: kindLabel(doc.kind), variant: "outline" };
  }

  const kinds = useMemo(
    () => Array.from(new Set(items.map((doc) => doc.kind))).sort(),
    [items]
  );
  const hasReports = items.some((doc) => doc.isReport);
  const selected = items.find((doc) => doc.id === selectedId) ?? null;

  const filters: { type: string; label: string }[] = [
    { type: "all", label: t("filters.all") },
    ...(hasReports ? [{ type: "report", label: t("filters.reports") }] : []),
    ...kinds.map((kind) => ({ type: kind, label: kindLabel(kind) })),
  ];

  const filtered = items.filter((doc) => {
    if (activeFilter === "all") return true;
    if (activeFilter === "report") return doc.isReport;
    return doc.kind === activeFilter;
  });

  function handleDeleted(id: string) {
    setItems((prev) => prev.filter((doc) => doc.id !== id));
    setSelectedId((prev) => (prev === id ? null : prev));
  }

  if (items.length === 0) {
    return <EmptyState />;
  }

  const activeFilterLabel =
    filters.find((filter) => filter.type === activeFilter)?.label ??
    activeFilter;

  return (
    <>
      <div className="flex flex-wrap gap-2">
        {filters.map((filter) => (
          <Button
            key={filter.type}
            type="button"
            variant={activeFilter === filter.type ? "default" : "outline"}
            size="sm"
            className="h-8 rounded-full px-4 text-sm"
            onClick={() => setActiveFilter(filter.type)}
          >
            {filter.label}
          </Button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <FilteredEmptyState filterLabel={activeFilterLabel} />
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {filtered.map((doc) => {
            const { label, variant } = badgeFor(doc);
            return (
              <Card
                key={doc.id}
                className="group cursor-pointer transition-shadow hover:shadow-md"
                onClick={() => setSelectedId(doc.id)}
              >
                <CardContent className="p-5">
                  <div className="mb-3 flex items-start gap-3">
                    <div className="mt-0.5 text-muted-foreground">
                      {kindIcon(doc.kind)}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="mb-1 line-clamp-2 text-sm font-medium leading-tight">
                        {doc.title}
                      </p>
                      <Badge variant={variant}>{label}</Badge>
                    </div>
                  </div>

                  <div className="mt-2 flex items-center justify-between">
                    <div className="flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
                      <Bot className="size-3 shrink-0" />
                      <span className="truncate">{doc.agentLabel}</span>
                      <span className="shrink-0">·</span>
                      <span className="shrink-0">
                        <RelativeTime iso={doc.createdAt} />
                      </span>
                    </div>

                    <DocumentActions
                      documentId={doc.id}
                      content={doc.content}
                      createdAt={doc.createdAt}
                      onDeleted={() => handleDeleted(doc.id)}
                      buttonClassName="size-7 opacity-0 transition-opacity group-hover:opacity-100"
                    />
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      <Dialog
        open={selected !== null}
        onOpenChange={(open) => !open && setSelectedId(null)}
      >
        {selected && (
          <DialogContent className="flex max-h-[80vh] max-w-2xl flex-col">
            <DialogHeader>
              <div className="flex items-start gap-3 pr-8">
                <div className="mt-1 text-muted-foreground">
                  {kindIcon(selected.kind)}
                </div>
                <div className="min-w-0 flex-1">
                  <DialogTitle className="text-left leading-tight">
                    {selected.title}
                  </DialogTitle>
                  <p className="mt-1 text-xs text-muted-foreground">
                    {selected.agentLabel} ·{" "}
                    <RelativeTime iso={selected.createdAt} />
                  </p>
                </div>
                <DocumentActions
                  documentId={selected.id}
                  content={selected.content}
                  createdAt={selected.createdAt}
                  onDeleted={() => handleDeleted(selected.id)}
                />
              </div>
            </DialogHeader>

            <ScrollArea className="mt-4 min-h-0 flex-1">
              {selected.content ? (
                <DocumentContent
                  kind={selected.kind}
                  title={selected.title}
                  content={selected.content}
                />
              ) : (
                <p className="text-sm italic text-muted-foreground">
                  {t("noContent")}
                </p>
              )}
            </ScrollArea>
          </DialogContent>
        )}
      </Dialog>
    </>
  );
}

function EmptyState() {
  const t = useTranslations("artifacts");
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <File className="mb-4 size-12 text-muted-foreground/40" />
      <h3 className="mb-1 text-lg font-semibold">{t("emptyState.title")}</h3>
      <p className="max-w-sm text-sm text-muted-foreground">
        {t("emptyState.description")}
      </p>
      {/* An empty artifacts page is a dead end without this: nothing
          on it produces an artifact — the chat surface does. */}
      <Button
        size="sm"
        className="mt-4"
        render={<Link href="/chat" />}
        nativeButton={false}
      >
        {t("emptyState.cta")}
      </Button>
    </div>
  );
}

function FilteredEmptyState({ filterLabel }: { filterLabel: string }) {
  const t = useTranslations("artifacts");
  const lowerFilterLabel = filterLabel.toLowerCase();
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <File className="mb-4 size-12 text-muted-foreground/40" />
      <h3 className="mb-1 text-lg font-semibold">
        {t("filteredEmptyState.title", { filterLabel: lowerFilterLabel })}
      </h3>
      <p className="text-sm text-muted-foreground">
        {t("filteredEmptyState.description", { filterLabel })}
      </p>
    </div>
  );
}

"use client";

/**
 * DocumentActions — per-artifact action cluster: copy full content to
 * the clipboard, and delete (with a confirm dialog whose copy matches
 * what `deleteLatestVersion` (`@/actions/documents`) actually does — see
 * that file's module doc comment for the underlying semantics: this can
 * revert an artifact to an earlier saved version rather than remove it
 * outright, and it refuses artifacts older than 30 days).
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { Check, Copy, Trash2 } from "lucide-react";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";

import { deleteLatestVersion } from "@/actions/documents";

interface DocumentActionsProps {
  documentId: string;
  content: string | null;
  createdAt: string;
  /** Called after a successful delete, e.g. to drop the item from local state. */
  onDeleted?: () => void;
  buttonClassName?: string;
}

export function DocumentActions({
  documentId,
  content,
  createdAt,
  onDeleted,
  buttonClassName,
}: DocumentActionsProps) {
  const t = useTranslations("artifacts");
  const router = useRouter();
  const [copied, setCopied] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [isDeleting, startDeleting] = useTransition();

  async function handleCopy() {
    if (!content) return;
    try {
      await navigator.clipboard.writeText(content);
      setCopied(true);
      toast.success(t("documentActions.copySuccess"));
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t("documentActions.copyErrorTitle"), {
        description: t("documentActions.copyErrorDescription"),
      });
    }
  }

  function handleDelete() {
    startDeleting(async () => {
      const result = await deleteLatestVersion(documentId, createdAt);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      toast.success(t("documentActions.deleteSuccess"));
      setConfirmOpen(false);
      onDeleted?.();
      router.refresh();
    });
  }

  return (
    <div className="flex items-center gap-1">
      {content && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={(event) => {
            event.stopPropagation();
            void handleCopy();
          }}
          className={buttonClassName}
          title={
            copied
              ? t("documentActions.copyTooltipCopied")
              : t("documentActions.copyTooltipDefault")
          }
        >
          {copied ? (
            <Check className="size-4 text-success" />
          ) : (
            <Copy className="size-4" />
          )}
        </Button>
      )}

      <Button
        type="button"
        variant="ghost"
        size="icon"
        onClick={(event) => {
          event.stopPropagation();
          setConfirmOpen(true);
        }}
        className={buttonClassName}
        title={t("documentActions.deleteTooltip")}
      >
        <Trash2 className="size-4" />
      </Button>

      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <DialogContent onClick={(event) => event.stopPropagation()}>
          <DialogHeader>
            <DialogTitle>{t("documentActions.deleteDialogTitle")}</DialogTitle>
            <DialogDescription>
              {t("documentActions.deleteDialogDescription")}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => setConfirmOpen(false)}
              disabled={isDeleting}
            >
              {t("documentActions.cancel")}
            </Button>
            <Button
              type="button"
              variant="destructive"
              onClick={handleDelete}
              disabled={isDeleting}
            >
              {isDeleting ? <Spinner /> : t("documentActions.delete")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

